{
  "assistantMessage": "초안을 준비했습니다. 확인 후 반영해 주세요.",
  "needsUserInput": false,
  "userQuestion": "",
  "toolCalls": [],
  "proposal": {
    "summary": "7월 27일부터 30일까지 출장 일정을 1건 추가합니다.",
    "operations": [
      {
        "action": "create_task",
        "title": "출장",
        "content": "",
        "taskTypeId": "type-etc",
        "projectId": "project-general",
        "status": "NOT_DONE",
        "startAt": "2026-07-27T09:00",
        "endAt": "2026-07-30T18:00",
        "isMajor": false
      }
    ]
  }
}

